using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OmensListsList", menuName = "Data/Battle/Omens System/Omen Data/OmensList Lists")]
public class OmensListsList : ScriptableObject
{
	[Serializable]
	public class OmenTierOmenDataList
	{
		public OmenTier omenTier;

		public List<OmenData> omenDatas = new List<OmenData>();

		public OmenTierOmenDataList(OmenTier omenTier)
		{
			this.omenTier = omenTier;
		}
	}

	[Header("Lists")]
	[SerializeField]
	private OmensList[] omensLists;

	[Header("Progression System")]
	[SerializeField]
	private Character[] characters;

	[SerializeField]
	private Character anyCharacter;

	[SerializeField]
	private Character moonieCharacter;

	[SerializeField]
	private Character cellariusCharacter;

	[SerializeField]
	private OmenTier[] omenTiers;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private GameController gameController;

	[Header("Runtime")]
	[SerializeField]
	private OmenTierOmenDataList[] currentCharacterUnlockedOmenTierOmenDatas;

	public List<string> DiscoveredBlessings = new List<string>();

	public OmenTierOmenDataList[] CurrentCharacterUnlockedOmenTierOmenDatas => currentCharacterUnlockedOmenTierOmenDatas;

	public OmenTierOmenDataList GetCurrentCharacterUnlockedOmenTierOmenDataList(OmenTier omenTier)
	{
		for (int i = 0; i < currentCharacterUnlockedOmenTierOmenDatas.Length; i++)
		{
			if (currentCharacterUnlockedOmenTierOmenDatas[i].omenTier == omenTier)
			{
				return currentCharacterUnlockedOmenTierOmenDatas[i];
			}
		}
		return null;
	}

	public void PopulateCurrentCharacterUnlockedOmenTierOmenDatas(bool isDailyRun = false)
	{
		PopulateLockedOmenDatas();
		OmenTierOmenDataList[] characterUnlockedOmenTierOmenDatas = GetCharacterUnlockedOmenTierOmenDatas(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter, isDailyRun);
		OmenTierOmenDataList[] characterUnlockedOmenTierOmenDatas2 = GetCharacterUnlockedOmenTierOmenDatas(anyCharacter, isDailyRun);
		currentCharacterUnlockedOmenTierOmenDatas = new OmenTierOmenDataList[omenTiers.Length];
		for (int i = 0; i < currentCharacterUnlockedOmenTierOmenDatas.Length; i++)
		{
			currentCharacterUnlockedOmenTierOmenDatas[i] = new OmenTierOmenDataList(omenTiers[i]);
		}
		for (int j = 0; j < currentCharacterUnlockedOmenTierOmenDatas.Length; j++)
		{
			currentCharacterUnlockedOmenTierOmenDatas[j].omenDatas.AddRange(characterUnlockedOmenTierOmenDatas[j].omenDatas.Duplicate());
			currentCharacterUnlockedOmenTierOmenDatas[j].omenDatas.AddRange(characterUnlockedOmenTierOmenDatas2[j].omenDatas.Duplicate());
		}
		for (int k = 0; k < currentCharacterUnlockedOmenTierOmenDatas.Length; k++)
		{
			for (int l = 0; l < currentCharacterUnlockedOmenTierOmenDatas[k].omenDatas.Count; l++)
			{
				currentCharacterUnlockedOmenTierOmenDatas[k].omenDatas.RemoveAll((OmenData omen) => !isDailyRun && omen.MuteForMod);
			}
		}
		if (!isDailyRun)
		{
			if ((ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == moonieCharacter && moonieCharacter.GetCharacterLevel() < 2) || (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == cellariusCharacter && cellariusCharacter.GetCharacterLevel() < 2))
			{
				RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas((OmenData omen) => omen.OmenID == "DaydreamsMask" || omen.OmenID == "QuanticFungus");
			}
			if ((ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == moonieCharacter && moonieCharacter.GetCharacterLevel() < 3) || (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == cellariusCharacter && cellariusCharacter.GetCharacterLevel() < 3))
			{
				RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas((OmenData omen) => omen.OmenID == "SagesCard");
			}
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == cellariusCharacter && cellariusCharacter.GetCharacterLevel() < 2)
			{
				RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas((OmenData omen) => omen.OmenID == "CondemnedReliquary");
			}
		}
		if (ReferenceSingleton<RunModifiersManager>.Instance.DicelessAnomalyRunModifierAction != null)
		{
			RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas((OmenData omen) => ReferenceSingleton<RunModifiersManager>.Instance.DicelessAnomalyRunModifierAction(omen));
		}
		for (int m = 0; m < ReferenceSingleton<RunModifiersManager>.Instance.RunModifiersHandler.ActiveRunModifiers.Count; m++)
		{
			RunModifier activeRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.RunModifiersHandler.ActiveRunModifiers[m];
			RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas((OmenData omen) => activeRunModifier.BlessingsToMute.Contains(omen));
		}
	}

	private void RemoveOmensFromCurrentCharacterUnlockedOmenTierOmenDatas(Func<OmenData, bool> match)
	{
		for (int i = 0; i < currentCharacterUnlockedOmenTierOmenDatas.Length; i++)
		{
			for (int j = 0; j < currentCharacterUnlockedOmenTierOmenDatas[i].omenDatas.Count; j++)
			{
				currentCharacterUnlockedOmenTierOmenDatas[i].omenDatas.RemoveAll((OmenData omen) => match(omen));
			}
		}
	}

	public void PopulateLockedOmenDatas()
	{
		if (!gameController.IsDemo)
		{
			List<OmenData> list = new List<OmenData>();
			for (int i = 0; i < characters.Length; i++)
			{
				list.AddRange(characters[i].GetLockedOmenDatas());
			}
			for (int j = 0; j < list.Count; j++)
			{
				list[j].SetCompendiumItemState(CompendiumItemState.Locked);
			}
		}
	}

	private OmenTierOmenDataList[] GetCharacterUnlockedOmenTierOmenDatas(Character character, bool isDailyRun)
	{
		OmenTierOmenDataList[] array = new OmenTierOmenDataList[omenTiers.Length];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = new OmenTierOmenDataList(omenTiers[i]);
		}
		List<OmenData> list = GetOmensList(character).OmenDatas.Duplicate();
		for (int j = 0; j < array.Length; j++)
		{
			for (int k = 0; k < list.Count; k++)
			{
				OmenData omenData = list[k];
				if ((isDailyRun || omenData.CompendiumItemState != CompendiumItemState.Locked) && (!gameController.IsDemo || !omenData.MuteForDemo) && omenData.OmenTier == array[j].omenTier)
				{
					array[j].omenDatas.Add(omenData);
				}
			}
		}
		return array;
	}

	public OmenData GetOmenData(string omenName)
	{
		OmenData omenData = null;
		for (int i = 0; i < omensLists.Length; i++)
		{
			omenData = omensLists[i].GetOmenData(omenName);
			if (omenData != null)
			{
				return omenData;
			}
		}
		return omenData;
	}

	public OmensList[] GetAllOmensList()
	{
		return omensLists;
	}

	public OmensList GetOmensList(Character character)
	{
		for (int i = 0; i < omensLists.Length; i++)
		{
			if (omensLists[i].Character == character)
			{
				return omensLists[i];
			}
		}
		return null;
	}

	public void LoadDiscoveredBlessings()
	{
		saveSystem.LoadDiscoveredBlessings();
		List<OmenData> list = new List<OmenData>();
		for (int i = 0; i < omensLists.Length; i++)
		{
			list.AddRange(omensLists[i].OmenDatas);
		}
		for (int j = 0; j < list.Count; j++)
		{
			if (list[j].CompendiumItemState != CompendiumItemState.Locked)
			{
				if (DiscoveredBlessings.Contains(list[j].name) || (list[j].name == "BehenianHourglassOmenData" && DiscoveredBlessings.Contains("BehenianChakramOmenData")) || (list[j].name == "VacuumWingsOmenData" && DiscoveredBlessings.Contains("VacuumsWingsOmenData")) || (list[j].name == "IlluminatingCompassOmenData" && DiscoveredBlessings.Contains("IluminatingCompassOmenData")) || (list[j].name == "RegalKhepreshOmenData" && DiscoveredBlessings.Contains("TaintedKhepreshOmenData")) || (list[j].name == "ContemplationSarcophagusOmenData" && DiscoveredBlessings.Contains("ContemplationSarcophogusOmenData")))
				{
					list[j].SetCompendiumItemState(CompendiumItemState.Discovered);
				}
				else
				{
					list[j].SetCompendiumItemState(CompendiumItemState.Undiscovered);
				}
			}
		}
	}

	public void BlessingsDiscovered(List<OmenData> omenDatas)
	{
		if (gameController.IsDemo)
		{
			return;
		}
		for (int i = 0; i < omenDatas.Count; i++)
		{
			if (omenDatas[i].CompendiumItemState != 0)
			{
				omenDatas[i].SetCompendiumItemState(CompendiumItemState.Discovered);
				DiscoveredBlessings.Add(omenDatas[i].name);
			}
		}
		saveSystem.SaveDiscoveredBlessings(saveAndStoreCache: true);
	}

	public void BlessingDiscovered(OmenData omenData)
	{
		if (!gameController.IsDemo)
		{
			if (omenData.CompendiumItemState != 0)
			{
				omenData.SetCompendiumItemState(CompendiumItemState.Discovered);
				DiscoveredBlessings.Add(omenData.name);
			}
			saveSystem.SaveDiscoveredBlessings(saveAndStoreCache: true);
		}
	}

	public void SetAllBlessingsToDiscovered()
	{
		List<OmenData> list = new List<OmenData>();
		OmensList[] allOmensList = GetAllOmensList();
		for (int i = 0; i < allOmensList.Length; i++)
		{
			list.AddRange(allOmensList[i].OmenDatas);
		}
		BlessingsDiscovered(list);
	}

	public void SetAllBlessingsToUndiscoveredOrLocked()
	{
		SetAllBlessingsToUndiscovered();
		PopulateLockedOmenDatas();
		DiscoveredBlessings.Clear();
		saveSystem.SaveDiscoveredBlessings(saveAndStoreCache: true);
	}

	public void SetAllBlessingsToUndiscovered()
	{
		OmensList[] allOmensList = GetAllOmensList();
		for (int i = 0; i < allOmensList.Length; i++)
		{
			List<OmenData> omenDatas = allOmensList[i].OmenDatas;
			for (int j = 0; j < omenDatas.Count; j++)
			{
				omenDatas[j].SetCompendiumItemState(CompendiumItemState.Undiscovered);
			}
		}
	}

	public float GetBlessingsDiscoveredAmount()
	{
		float num = 0f;
		for (int i = 0; i < omensLists.Length; i++)
		{
			List<OmenData> omenDatas = omensLists[i].OmenDatas;
			for (int j = 0; j < omenDatas.Count; j++)
			{
				if (omenDatas[j].CompendiumItemState == CompendiumItemState.Discovered)
				{
					num += 1f;
				}
			}
		}
		return num;
	}

	public float GetBlessingsTotal()
	{
		float num = 0f;
		for (int i = 0; i < omensLists.Length; i++)
		{
			num += (float)omensLists[i].OmenDatas.Count;
		}
		return num;
	}

	public float GetCharacterBlessingsDiscoveredAmount(Character character)
	{
		float num = 0f;
		List<OmenData> omenDatas = GetOmensList(character).OmenDatas;
		for (int i = 0; i < omenDatas.Count; i++)
		{
			if (omenDatas[i].CompendiumItemState == CompendiumItemState.Discovered)
			{
				num += 1f;
			}
		}
		return num;
	}
}
